-- ====================================================================
-- 04_补范围限定.sql —— 给未做「企业/报告范围限定」的表补条件
-- （自动生成，dry-run 产出，**未执行**）
--
-- 准则：每张被引用的表（含 JOIN / 子查询 / 派生表）都必须带
--       reportNo + entName 两个严格条件，否则会跨企业 / 跨报告取数。
--
-- 补法：**不新增任何表、不新增任何 JOIN**。这些表本来就在 SQL 里，
--       只在它**已有的作用域**里追加两个 AND：
--         · LEFT JOIN 的右表 → 追加到该 JOIN 的 ON 子句末尾
--           （放 WHERE 会让 LEFT JOIN 退化成 INNER JOIN，改变左表行数）
--         · 块内 FROM 主表   → 追加到该块 WHERE 末尾（无 WHERE 则新起一个）
--         · 子查询内的表     → 同规则，作用在该子查询自己的区间
--         · 派生表 (SELECT …) t 本身无法加条件 → 跳过（其内部表另行处理）
--
-- ⚠️ 本文件会再次 UPDATE 同一个 script 字段，**必须排在 02_入参规范化.sql 之后**。
--    每条语句的值都是「终态」（含 02 的归一化结果 + 本次补的条件），
--    因此单独执行本文件也不会退回旧写法。
-- 执行顺序：01_备份.sql -> 02_入参规范化.sql -> 03_校验.sql -> 本文件
-- ====================================================================

UPDATE index_params SET script = $mig$
{"dataSource":"bosz-dev-local-0001","sql":"SELECT\n    i.ZXREPORTNOZX AS 征信报告记录号最新,\n    i.ZXREPORTNOSQ AS 征信报告记录号上期,\n    i.ZXREPORTNOSX AS 征信报告记录号授信,\n    i.ID AS ID,\n    i.EDUCATION AS 学历,\n    i.GUARANTORNAME AS 担保人,\n    i.GUARANTORTYPE AS 担保人类型,\n    i.ISSTATEOWNED AS 是否国有担保,\n    i.INPUTTIME AS 入库时间,\n    i.GUARANTORID AS 担保人客户编号,\n    i.SUBJECTTYPE AS 主体类型,\n    i.CUSTOMERID AS 客户编号,\n    i.CUSTOMERNAME AS 客户名称,\n    c.isTechCompany AS 是否科创企业,\n    c.actualController AS 实际控制人,\n    CASE\n        WHEN c.actualController IS NOT NULL\n             AND POSITION(i.GUARANTORNAME IN c.actualController) > 0\n        THEN '是'\n        ELSE '否'\n    END AS 担保人是否是实控人,\n    u.creditSum AS 授信金额,\n    i.REPORTNO AS 报告编号\nFROM APP_GUARANTOR_INFO i\nLEFT JOIN APP_CUSTOMER_INFO c\n    ON i.customerid = c.customerId\n    AND i.customername = c.customerName\n    AND c.reportno = :reportNo\n    AND c.customername = :entName\nLEFT JOIN APP_CREDIT_USE_INFO u\n    ON i.reportno = u.reportNo\n    AND i.customerid = u.customerId\n    AND i.customername = u.customername\n    AND u.reportno = :reportNo\n    AND u.customername = :entName\nWHERE i.reportno = :reportNo\n  AND i.customername = :entName\n  AND i.guarantorname= :guarantorName","paramData":[{"id":"a91d40f8-c3cf-4c27-d73e-dbbe285a567d","name":"reportNo","desc":"","type":"1","isSync":"Y","defaultValue":"'RPT-202603-001'","relateIndex":null},{"id":"2a99a756-74a6-70de-0f45-8a3e5071c7e8","name":"entName","desc":"","type":"1","isSync":"Y","defaultValue":"'苏州XX精密机械制造有限公司'","relateIndex":null},{"id":"987a7d66-787c-728d-c214-a3e0085b5fac","name":"guarantorName","desc":"","type":"1","isSync":"Y","defaultValue":"'泰州公司'","relateIndex":null}],"moduleCode":"","knowledgeCode":"","knowledgeName":"","knowledgeGroupInfo":[],"withModelSummary":false,"knowledgeParamList":[{"key":"1","paramName":"entName","paramValue":"科大讯飞股份有限公司"}],"entName":"科大讯飞股份有限公司"}
