{"dataSource":"bosz-dev-local-0001","sql":"SELECT\n\n    i.ID AS ID,\n\n    i.REPORTNO AS 报告编号,\n\n    i.CUSTOMERID AS 客户编号,\n\n    i.CUSTOMERNAME AS 客户名称,\n\n    i.GUARANTORNAME AS 担保人,\n\n    i.QUERYTIME AS 征信查询时间,\n\n    i.ZXREPORTNO AS 征信报告记录号,\n\n    i.TOTALLOANBAL AS 贷款余额合计,\n\n    i.OPERATELOANBAL AS 经营性贷款余额合计,\n\n    i.CONSUMELOANBAL AS 消费类贷款余额合计,\n\n    i.HOUSELOANBAL AS 住房类贷款余额合计,\n\n    i.OTHERLOANBAL AS 其他贷款余额合计,\n\n    i.TOTALLOANCOUNT AS 贷款机构数,\n\n    i.OPERATELOANCOUNT AS 经营性贷款机构数,\n\n    i.CONSUMELOANCOUNT AS 消费类贷款机构数,\n\n    i.HOUSELOANCOUNT AS 住房类贷款机构数,\n\n    i.OTHERLOANCOUNT AS 其他贷款机构数,\n\n    i.BADBAL AS 呆账余额,\n\n    i.BZCBAL AS 被追偿余额,\n\n    i.LOANCURRENTOVERDUE AS 贷款当前逾期总金额,\n\n    i.CARDCURRENTOVERDUE AS 贷记卡当前逾期总金额,\n\n    i.GUARANTEEOVERDUEAMT AS 对外担保相关还款责任当前逾期金额,\n\n    i.NONBANKGUARANTEEBAL AS 在非银机构对外担保余额,\n\n    i.NONBANKHIGHRATELOAN AS 非银机构较高利率借款推算利率最大值,\n\n    i.GUARANTEEABNORMALBAL AS 对外担保相关还款责任五级分类非正常余额,\n\n    i.EXTENDBAL AS 展期债务余额,\n\n    i.DELAYBAL AS 落实金融困等政策银行主动延期债务余额,\n\n    i.CREDITABNORMALBAL AS 未结清信贷五级分类非正常余额,\n\n    i.ACCTABNORMALBAL AS 未结清账户状态非正常余额,\n\n    i.CARDABNORMALBAL AS 未销户贷记卡账户状态非正常余额,\n\n    i.GUARANTEEHKABNORMALBAL AS 对外担保相关还款责任还款状态非正常余额,\n\n    i.CREDITUSERATE AS 信用卡使用率,\n\n    i.INPUTTIME AS 入库时间,\n\n    i.GUARANTORID AS 担保人客户编号,\n\n    i.NONBANKLIABTOTAL AS 在非银机构负债合计,\n\n    i.LOANQUERY12M AS 近一年贷款审批征信查询次数,\n\n    i.LOANQUERY6M AS 近6个月贷款审批征信查询次数,\n\n    i.CARDQUERY6M AS 近6个月信用卡审批征信查询次数,\n\n    i.LOANQUERY3M AS 近3个月贷款审批征信查询次数,\n\n    i.CARDQUERY12M AS 近一年信用卡审批征信查询次数,\n\n    i.CARDQUERY3M AS 近3个月信用卡审批征信查询次数,\n\n    i.SELFQUERY1M AS 近1个月本人查询征信查询次数,\n\n    CURRENT_DATE - CAST(i.QUERYTIME AS DATE) AS 最新一期征信查询时间距当前时间天数\n\nFROM APP_GUARANTOR_CREDIT_INFO i\n\nINNER JOIN APP_GUARANTOR_INFO g\n\n    ON i.ZXREPORTNO = g.ZXREPORTNOZX\n\nWHERE g.reportno = :reportNo\n\n  AND g.customername = :entName\n\n  AND g.guarantorname = :guarantorName\n  AND i.reportno = :reportNo\n  AND i.customername = :entName","paramData":[{"id":"5ff1afc1-152f-3f24-67ee-6b7b03838352","name":"reportNo","desc":"","type":"1","isSync":"Y","defaultValue":"'RPT-202603-001'","relateIndex":null},{"id":"6a9d5ed2-eea7-5953-1b34-0a8566ad987a","name":"entName","desc":"","type":"1","isSync":"Y","defaultValue":"'苏州XX精密机械制造有限公司'","relateIndex":null},{"id":"a6a33a63-43f8-df63-34e5-9b804fdb41b5","name":"guarantorName","desc":"","type":"1","isSync":"Y","defaultValue":"'张三'","relateIndex":null}],"moduleCode":"","knowledgeCode":"","knowledgeName":"","knowledgeGroupInfo":[],"withModelSummary":false,"knowledgeParamList":[{"key":"1","paramName":"entName","paramValue":"科大讯飞股份有限公司"}],"entName":"科大讯飞股份有限公司"}
