{"dataSource":"bosz-dev-local-0001","sql":"SELECT   \n    MAX(CASE WHEN i.ZXREPORTNO = g.ZXREPORTNOZX THEN i.WORKINGCAPITALLOANBAL END) AS 流贷金额最新时点,  \n     \n    MAX(CASE WHEN i.ZXREPORTNO = g.zxReportNoSQ THEN i.WORKINGCAPITALLOANBAL END) AS 流贷金额上期时点,  \n     \n    MAX(CASE WHEN i.ZXREPORTNO = g.zxReportNoSX THEN i.WORKINGCAPITALLOANBAL END) AS 流贷金额授信时点,\n\n    MAX(CASE WHEN i.ZXREPORTNO = g.ZXREPORTNOZX THEN i.WORKINGCAPITALLOANBAL END)\n    - MAX(CASE WHEN i.ZXREPORTNO = g.zxReportNoSQ THEN i.WORKINGCAPITALLOANBAL END) AS 流贷金额最新较上期增加值,\n\n    MAX(CASE WHEN i.ZXREPORTNO = g.ZXREPORTNOZX THEN i.WORKINGCAPITALLOANBAL END)\n    - MAX(CASE WHEN i.ZXREPORTNO = g.zxReportNoSX THEN i.WORKINGCAPITALLOANBAL END) AS 流贷金额最新较授信增加值,\n\n    MAX(CASE WHEN i.ZXREPORTNO = g.ZXREPORTNOZX THEN i.QUERYTIME END) AS 最新征信查询日期,\n\n    MAX(CASE WHEN i.ZXREPORTNO = g.zxReportNoSQ THEN i.QUERYTIME END) AS 上期征信查询日期,\n\n    MAX(CASE WHEN i.ZXREPORTNO = g.zxReportNoSX THEN i.QUERYTIME END) AS 授信征信查询日期\n  \nFROM APP_CREDIT_REPORT_INFO i   \nINNER JOIN APP_GUARANTOR_INFO g   \n    ON i.ZXREPORTNO IN (g.ZXREPORTNOZX, g.zxReportNoSQ, g.zxReportNoSX)   \nWHERE g.reportno = :reportNo   \n  AND g.customername = :entName   \n  AND g.guarantorname = :guarantorName\n  AND i.reportno = :reportNo\n  AND i.customername = :entName","paramData":[{"id":"2a9152b1-8542-a0db-0c17-d11b59c4d460","name":"reportNo","desc":"","type":"1","isSync":"Y","defaultValue":"'RPT-202603-001'","relateIndex":null},{"id":"bd138d27-b35d-1604-20e3-ac40f629e622","name":"entName","desc":"","type":"1","isSync":"Y","defaultValue":"'苏州XX精密机械制造有限公司'","relateIndex":null},{"id":"63fa1a6a-7dec-c102-848f-8cd76318565c","name":"guarantorName","desc":"","type":"1","isSync":"Y","defaultValue":"'泰州公司'","relateIndex":null}],"moduleCode":"","knowledgeCode":"","knowledgeName":"","knowledgeGroupInfo":[],"withModelSummary":false,"knowledgeParamList":[{"key":"1","paramName":"entName","paramValue":"科大讯飞股份有限公司"}],"entName":"科大讯飞股份有限公司"}
