UPDATE index_params SET script = $mig$
{"dataSource":"bosz-dev-local-0001","sql":"SELECT \n    MAX(CASE WHEN i.ZXREPORTNO = g.ZXREPORTNOZX THEN i.NONBANKHIGHRATELOAN END) AS 非银机构较高利率借款推算利率最大值最新时点,\n    \n    MAX(CASE WHEN i.ZXREPORTNO = g.zxReportNoSQ THEN i.NONBANKHIGHRATELOAN END) AS 非银机构较高利率借款推算利率最大值上期时点,\n    \n    CASE\n        WHEN MAX(CASE WHEN i.ZXREPORTNO = g.zxReportNoSQ THEN i.NONBANKHIGHRATELOAN END) IS NULL\n          OR MAX(CASE WHEN i.ZXREPORTNO = g.zxReportNoSQ THEN i.NONBANKHIGHRATELOAN END) = 0\n        THEN NULL\n        ELSE (\n            MAX(CASE WHEN i.ZXREPORTNO = g.ZXREPORTNOZX THEN i.NONBANKHIGHRATELOAN END)\n            - MAX(CASE WHEN i.ZXREPORTNO = g.zxReportNoSQ THEN i.NONBANKHIGHRATELOAN END)\n        )\n        / MAX(CASE WHEN i.ZXREPORTNO = g.zxReportNoSQ THEN i.NONBANKHIGHRATELOAN END) * 100\n    END AS 非银机构较高利率借款推算利率最大值增长率\n\nFROM app_guarantor_credit_info  i \nINNER JOIN APP_GUARANTOR_INFO g \n    ON i.ZXREPORTNO IN (g.ZXREPORTNOZX, g.zxReportNoSQ) \nWHERE g.reportno = :reportNo \n  AND g.customername = :entName \n  AND g.guarantorname = :guarantorName\n  AND i.reportno = :reportNo\n  AND i.customername = :entName","paramData":[{"id":"2a9152b1-8542-a0db-0c17-d11b59c4d460","name":"reportNo","desc":"","type":"1","isSync":"Y","defaultValue":"'RPT-202603-001'","relateIndex":null},{"id":"bd138d27-b35d-1604-20e3-ac40f629e622","name":"entName","desc":"","type":"1","isSync":"Y","defaultValue":"'苏州XX精密机械制造有限公司'","relateIndex":null},{"id":"63fa1a6a-7dec-c102-848f-8cd76318565c","name":"guarantorName","desc":"","type":"1","isSync":"Y","defaultValue":"'张三'","relateIndex":null}],"moduleCode":"","knowledgeCode":"","knowledgeName":"","knowledgeGroupInfo":[],"withModelSummary":false,"knowledgeParamList":[{"key":"1","paramName":"entName","paramValue":"科大讯飞股份有限公司"}],"entName":"科大讯飞股份有限公司"}
$mig$ WHERE paramno = '2095818594668523522';

UPDATE index_params SET script = $mig$
{"dataSource":"bosz-dev-local-0001","sql":"SELECT \n    -- 在非银机构对外担保余额\n    MAX(CASE \n        WHEN i.ZXREPORTNO = g.ZXREPORTNOZX \n        THEN i.NONBANKGUARANTEEBAL \n    END) AS 在非银机构对外担保余额最新值,\n\n    MAX(CASE \n        WHEN i.ZXREPORTNO = g.zxReportNoSX \n        THEN i.NONBANKGUARANTEEBAL \n    END) AS 在非银机构对外担保余额授信时值,\n\n    MAX(CASE \n        WHEN i.ZXREPORTNO = g.ZXREPORTNOZX \n        THEN i.NONBANKGUARANTEEBAL \n    END) - \n    MAX(CASE \n        WHEN i.ZXREPORTNO = g.zxReportNoSX \n        THEN i.NONBANKGUARANTEEBAL \n    END) AS 在非银机构对外担保余额较授信增长值,\n\n\n    -- 在非银机构负债合计\n    MAX(CASE \n        WHEN i.ZXREPORTNO = g.ZXREPORTNOZX \n        THEN i.NONBANKLIABTOTAL \n    END) AS 在非银机构负债合计最新值,\n\n    MAX(CASE \n        WHEN i.ZXREPORTNO = g.zxReportNoSX \n        THEN i.NONBANKLIABTOTAL \n    END) AS 在非银机构负债合计授信时值,\n\n    MAX(CASE \n        WHEN i.ZXREPORTNO = g.ZXREPORTNOZX \n        THEN i.NONBANKLIABTOTAL \n    END) - \n    MAX(CASE \n        WHEN i.ZXREPORTNO = g.zxReportNoSX \n        THEN i.NONBANKLIABTOTAL \n    END) AS 在非银机构负债合计较授信增长值\n\nFROM app_guarantor_credit_info i \nINNER JOIN APP_GUARANTOR_INFO g \n    ON i.ZXREPORTNO IN (g.ZXREPORTNOZX, g.zxReportNoSX) \nWHERE g.reportno = :reportNo \n  AND g.customername = :entName \n  AND g.guarantorname = :guarantorName\n  AND i.reportno = :reportNo\n  AND i.customername = :entName","paramData":[{"id":"2a9152b1-8542-a0db-0c17-d11b59c4d460","name":"reportNo","desc":"","type":"1","isSync":"Y","defaultValue":"'RPT-202603-001'","relateIndex":null},{"id":"bd138d27-b35d-1604-20e3-ac40f629e622","name":"entName","desc":"","type":"1","isSync":"Y","defaultValue":"'苏州XX精密机械制造有限公司'","relateIndex":null},{"id":"63fa1a6a-7dec-c102-848f-8cd76318565c","name":"guarantorName","desc":"","type":"1","isSync":"Y","defaultValue":"'张三'","relateIndex":null}],"moduleCode":"","knowledgeCode":"","knowledgeName":"","knowledgeGroupInfo":[],"withModelSummary":false,"knowledgeParamList":[{"key":"1","paramName":"entName","paramValue":"科大讯飞股份有限公司"}],"entName":"科大讯飞股份有限公司"}
$mig$ WHERE paramno = '2095827833919123457';

UPDATE index_params SET script = $mig$
{"dataSource":"bosz-dev-local-0001","sql":"SELECT\n    -- 剔除我行对外担保最新值\n    MAX(\n        CASE\n            WHEN i.ZXREPORTNO = g.ZXREPORTNOZX\n            THEN i.GUARANTEEBALANCEEXBANK\n        END\n    ) AS 剔除我行对外担保最新值,\n\n    -- 剔除我行对外担保授信值\n    MAX(\n        CASE\n            WHEN i.ZXREPORTNO = g.zxReportNoSX\n            THEN i.GUARANTEEBALANCEEXBANK\n        END\n    ) AS 剔除我行对外担保授信值,\n\n    -- 剔除我行对外担保较授信增长率\n    CASE\n        WHEN MAX(\n            CASE\n                WHEN i.ZXREPORTNO = g.zxReportNoSX\n                THEN i.GUARANTEEBALANCEEXBANK\n            END\n        ) IS NULL\n        OR MAX(\n            CASE\n                WHEN i.ZXREPORTNO = g.zxReportNoSX\n                THEN i.GUARANTEEBALANCEEXBANK\n            END\n        ) = 0\n        THEN NULL\n\n        ELSE\n            (\n                MAX(\n                    CASE\n                        WHEN i.ZXREPORTNO = g.ZXREPORTNOZX\n                        THEN i.GUARANTEEBALANCEEXBANK\n                    END\n                )\n                -\n                MAX(\n                    CASE\n                        WHEN i.ZXREPORTNO = g.zxReportNoSX\n                        THEN i.GUARANTEEBALANCEEXBANK\n                    END\n                )\n            )\n            /\n            MAX(\n                CASE\n                    WHEN i.ZXREPORTNO = g.zxReportNoSX\n                    THEN i.GUARANTEEBALANCEEXBANK\n                END\n            )\n            * 100\n    END AS 剔除我行对外担保较授信增长率\n\nFROM APP_CREDIT_REPORT_INFO i\nINNER JOIN APP_GUARANTOR_INFO g\n    ON i.ZXREPORTNO IN (g.ZXREPORTNOZX, g.zxReportNoSX)\nWHERE g.reportno = :reportNo\n  AND g.customername = :entName\n  AND g.guarantorname = :guarantorName\n  AND i.reportno = :reportNo\n  AND i.customername = :entName","paramData":[{"id":"2a9152b1-8542-a0db-0c17-d11b59c4d460","name":"reportNo","desc":"","type":"1","isSync":"Y","defaultValue":"'RPT-202603-001'","relateIndex":null},{"id":"bd138d27-b35d-1604-20e3-ac40f629e622","name":"entName","desc":"","type":"1","isSync":"Y","defaultValue":"'苏州XX精密机械制造有限公司'","relateIndex":null},{"id":"63fa1a6a-7dec-c102-848f-8cd76318565c","name":"guarantorName","desc":"","type":"1","isSync":"Y","defaultValue":"'泰州公司'","relateIndex":null}],"moduleCode":"","knowledgeCode":"","knowledgeName":"","knowledgeGroupInfo":[],"withModelSummary":false,"knowledgeParamList":[{"key":"1","paramName":"entName","paramValue":"科大讯飞股份有限公司"}],"entName":"科大讯飞股份有限公司"}
$mig$ WHERE paramno = '2095833592136478721';

UPDATE index_params SET script = $mig$
{"dataSource":"bosz-dev-local-0001","sql":"SELECT\n    COALESCE(x.CUSTOMERID, g.CUSTOMERID) AS 客户编号,\n    COALESCE(x.CUSTOMERNAME, g.CUSTOMERNAME) AS 客户名称,\n    COALESCE(x.NAME, g.NAME) AS 股东名称,\n    x.NAME AS 信贷股东名称,\n    g.NAME AS 工商股东名称,\n    CASE\n        WHEN x.NAME IS NULL THEN '工商有、信贷无'\n        WHEN g.NAME IS NULL THEN '信贷有、工商无'\n    END AS 对比结果\nFROM APP_XD_SHAREHOLDER_INFO x\nFULL OUTER JOIN APP_SHAREHOLDER_INFO g\n    ON x.CUSTOMERID = g.CUSTOMERID\n    AND x.NAME = g.NAME\n    AND g.reportno = :reportNo\n    AND g.customername = :entName\nWHERE COALESCE(x.REPORTNO, g.REPORTNO) = :reportNo\nAND COALESCE(x.CUSTOMERNAME, g.CUSTOMERNAME) = :entName\nAND (x.NAME IS NULL OR g.NAME IS NULL)\n  AND x.reportno = :reportNo\n  AND x.customername = :entName","paramData":[{"id":"aaa66566-dbcc-e75c-fb3a-daecfeaa2200","name":"reportNo","desc":"","type":"1","isSync":"Y","defaultValue":"'RPT-202603-001'","relateIndex":null},{"id":"fb2fd6b5-b1f5-ffbc-e170-ed7d91551643","name":"entName","desc":"","type":"1","isSync":"Y","defaultValue":"'苏州XX精密机械制造有限公司'","relateIndex":null}],"moduleCode":"","knowledgeCode":"","knowledgeName":"","knowledgeGroupInfo":[],"withModelSummary":false,"knowledgeParamList":[{"key":"1","paramName":"entName","paramValue":"科大讯飞股份有限公司"}],"entName":"科大讯飞股份有限公司"}
$mig$ WHERE paramno = '2097286270184075265';

UPDATE index_params SET script = $mig$
{"dataSource":"bosz-dev-local-0001","sql":"SELECT\n    CASE\n        WHEN COUNT(CASE WHEN x.NAME IS NULL OR g.NAME IS NULL THEN 1 END) > 0 THEN '否'\n        ELSE '是'\n    END AS 股东是否一致\nFROM APP_XD_SHAREHOLDER_INFO x\nFULL OUTER JOIN APP_SHAREHOLDER_INFO g\n    ON x.CUSTOMERID = g.CUSTOMERID\n    AND x.NAME = g.NAME\n    AND g.reportno = :reportNo\n    AND g.customername = :entName\nWHERE COALESCE(x.REPORTNO, g.REPORTNO) = :reportNo\nAND COALESCE(x.CUSTOMERNAME, g.CUSTOMERNAME) = :entName\n  AND x.reportno = :reportNo\n  AND x.customername = :entName","paramData":[{"id":"aaa66566-dbcc-e75c-fb3a-daecfeaa2200","name":"reportNo","desc":"","type":"1","isSync":"Y","defaultValue":"'RPT-202603-001'","relateIndex":null},{"id":"fb2fd6b5-b1f5-ffbc-e170-ed7d91551643","name":"entName","desc":"","type":"1","isSync":"Y","defaultValue":"'苏州XX精密机械制造有限公司'","relateIndex":null}],"moduleCode":"","knowledgeCode":"","knowledgeName":"","knowledgeGroupInfo":[],"withModelSummary":false,"knowledgeParamList":[{"key":"1","paramName":"entName","paramValue":"科大讯飞股份有限公司"}],"entName":"科大讯飞股份有限公司"}
$mig$ WHERE paramno = '2097289009907642370';

UPDATE index_params SET script = $mig$
{"dataSource":"bosz-dev-local-0001","sql":"SELECT\n    c.LEGALPERSON AS 信贷系统法人,\n    i.ICLEGALPERSON AS 外部工商法人,\n    CASE\n        WHEN c.LEGALPERSON = i.ICLEGALPERSON THEN '是'\n        ELSE '否'\n    END AS 是否一致\nFROM APP_CUSTOMER_INFO c\nLEFT JOIN APP_IC_INFO i\n    ON c.REPORTNO = i.REPORTNO\n    AND c.CUSTOMERID = i.CUSTOMERID\n    AND c.CUSTOMERNAME = i.CUSTOMERNAME\n    AND i.reportno = :reportNo\n    AND i.customername = :entName\nWHERE c.REPORTNO = :reportNo\nAND c.CUSTOMERNAME = :entName","paramData":[{"id":"aaa66566-dbcc-e75c-fb3a-daecfeaa2200","name":"reportNo","desc":"","type":"1","isSync":"Y","defaultValue":"'RPT-202603-001'","relateIndex":null},{"id":"fb2fd6b5-b1f5-ffbc-e170-ed7d91551643","name":"entName","desc":"","type":"1","isSync":"Y","defaultValue":"'苏州XX精密机械制造有限公司'","relateIndex":null}],"moduleCode":"","knowledgeCode":"","knowledgeName":"","knowledgeGroupInfo":[],"withModelSummary":false,"knowledgeParamList":[{"key":"1","paramName":"entName","paramValue":"科大讯飞股份有限公司"}],"entName":"科大讯飞股份有限公司"}
$mig$ WHERE paramno = '2097290064745738241';

UPDATE index_params SET script = $mig$
{"dataSource":"bosz-dev-local-0001","sql":"SELECT\n    c.CUSTOMERID AS 客户编号,\n    c.CUSTOMERNAME AS 客户名称,\n    c.CREDITDATE AS 授信日期,\n    s.ICSHAREHOLDERNAME AS 股东名称,\n    s.icStockNum AS 持股数,\n    s.icAmount AS 投资金额,\n    s.CHANGETIME AS 变更时间,\n    s.PERCENTBEFORE AS 变更前持股比例,\n    s.PERCENTAFTER AS 变更后持股比例,\n    g.IS_STATE_OWNED AS 是否国有,\n    CASE\n        WHEN s.PERCENTBEFORE < 20 AND s.PERCENTAFTER >= 20\n            THEN '新增'\n        WHEN s.PERCENTBEFORE >= 20 AND s.PERCENTAFTER < 20\n            THEN '退出'\n        WHEN s.PERCENTBEFORE >= 20 AND s.PERCENTAFTER >= 20\n             AND s.PERCENTAFTER > s.PERCENTBEFORE\n            THEN '上升'\n        WHEN s.PERCENTBEFORE >= 20 AND s.PERCENTAFTER >= 20\n             AND s.PERCENTAFTER < s.PERCENTBEFORE\n            THEN '下降'\n        ELSE '其他'\n    END AS 变更类型\nFROM APP_CREDIT_USE_INFO c\nINNER JOIN APP_IC_SHAREHOLDER_INFO s\n    ON c.CUSTOMERID = s.CUSTOMERID\n    AND s.reportno = :reportNo\n    AND s.customername = :entName\nLEFT JOIN APP_SHAREHOLDER_INFO g\n    ON s.CUSTOMERID = g.CUSTOMERID\n    AND s.ICSHAREHOLDERNAME = g.NAME\n    AND g.reportno = :reportNo\n    AND g.customername = :entName\nWHERE c.REPORTNO = :reportNo\nAND c.CUSTOMERNAME = :entName\nAND s.CHANGETIME > c.CREDITDATE\nAND (\n    s.PERCENTBEFORE >= 20\n    OR s.PERCENTAFTER >= 20\n)\nAND s.PERCENTBEFORE <> s.PERCENTAFTER","paramData":[{"id":"aaa66566-dbcc-e75c-fb3a-daecfeaa2200","name":"reportNo","desc":"","type":"1","isSync":"Y","defaultValue":"'RPT-202603-001'","relateIndex":null},{"id":"fb2fd6b5-b1f5-ffbc-e170-ed7d91551643","name":"entName","desc":"","type":"1","isSync":"Y","defaultValue":"'苏州XX精密机械制造有限公司'","relateIndex":null}],"moduleCode":"","knowledgeCode":"","knowledgeName":"","knowledgeGroupInfo":[],"withModelSummary":false,"knowledgeParamList":[{"key":"1","paramName":"entName","paramValue":"科大讯飞股份有限公司"}],"entName":"科大讯飞股份有限公司"}
$mig$ WHERE paramno = '2097298221127708674';

UPDATE index_params SET script = $mig$
{"dataSource":"bosz-dev-local-0001","sql":"SELECT\n    CASE\n        WHEN COUNT(*) > 0 THEN '是'\n        ELSE '否'\n    END AS 是否存在重要股东变更\nFROM APP_CREDIT_USE_INFO c\nINNER JOIN APP_IC_SHAREHOLDER_INFO s\n    ON c.CUSTOMERID = s.CUSTOMERID\n    AND s.reportno = :reportNo\n    AND s.customername = :entName\nLEFT JOIN APP_SHAREHOLDER_INFO g\n    ON s.CUSTOMERID = g.CUSTOMERID\n    AND s.ICSHAREHOLDERNAME = g.NAME\n    AND g.reportno = :reportNo\n    AND g.customername = :entName\nWHERE c.REPORTNO = :reportNo\nAND c.CUSTOMERNAME = :entName\nAND s.CHANGETIME > c.CREDITDATE\nAND (\n    s.PERCENTBEFORE >= 20\n    OR s.PERCENTAFTER >= 20\n)\nAND s.PERCENTBEFORE <> s.PERCENTAFTER","paramData":[{"id":"aaa66566-dbcc-e75c-fb3a-daecfeaa2200","name":"reportNo","desc":"","type":"1","isSync":"Y","defaultValue":"'RPT-202603-001'","relateIndex":null},{"id":"fb2fd6b5-b1f5-ffbc-e170-ed7d91551643","name":"entName","desc":"","type":"1","isSync":"Y","defaultValue":"'苏州XX精密机械制造有限公司'","relateIndex":null}],"moduleCode":"","knowledgeCode":"","knowledgeName":"","knowledgeGroupInfo":[],"withModelSummary":false,"knowledgeParamList":[{"key":"1","paramName":"entName","paramValue":"科大讯飞股份有限公司"}],"entName":"科大讯飞股份有限公司"}
$mig$ WHERE paramno = '2097301442667753473';

UPDATE index_params SET script = $mig$
{"dataSource":"bosz-dev-local-0001","sql":"SELECT\n    i.CUSTOMERID AS 客户编号,\n    i.CUSTOMERNAME AS 客户名称,\n\n    -- 1、借款人是否假冒国企\n    CASE\n        WHEN i.ISFAKESTATEOWNED = '是' THEN '是'\n        ELSE '否'\n    END AS 借款人是否假冒国企,\n\n    -- 2、是否有股东假冒国企\n    CASE\n        WHEN EXISTS (\n            SELECT 1\n            FROM APP_SHAREHOLDER_INFO s\n            WHERE s.CUSTOMERID = i.CUSTOMERID\n              AND s.IS_FAKE_STATE_OWNED = '是'\n  AND s.reportno = :reportNo\n  AND s.customername = :entName\n        )\n        THEN '是'\n        ELSE '否'\n    END AS 是否有股东假冒国企,\n\n    -- 3、假冒国企的股东名称\n    (\n        SELECT LISTAGG(s.NAME, '、')\n               WITHIN GROUP (ORDER BY s.NAME)\n        FROM APP_SHAREHOLDER_INFO s\n        WHERE s.CUSTOMERID = i.CUSTOMERID\n          AND s.IS_FAKE_STATE_OWNED = '是'\n  AND s.reportno = :reportNo\n  AND s.customername = :entName\n    ) AS 假冒国企股东名称\n\nFROM APP_IC_INFO i\nWHERE i.REPORTNO = :reportNo\nAND i.CUSTOMERNAME = :entName","paramData":[{"id":"aaa66566-dbcc-e75c-fb3a-daecfeaa2200","name":"reportNo","desc":"","type":"1","isSync":"Y","defaultValue":"'RPT-202603-001'","relateIndex":null},{"id":"fb2fd6b5-b1f5-ffbc-e170-ed7d91551643","name":"entName","desc":"","type":"1","isSync":"Y","defaultValue":"'苏州XX精密机械制造有限公司'","relateIndex":null}],"moduleCode":"","knowledgeCode":"","knowledgeName":"","knowledgeGroupInfo":[],"withModelSummary":false,"knowledgeParamList":[{"key":"1","paramName":"entName","paramValue":"科大讯飞股份有限公司"}],"entName":"科大讯飞股份有限公司"}
$mig$ WHERE paramno = '2097494825562550273';

UPDATE index_params SET script = $mig$
{"dataSource":"bosz-dev-local-0001","sql":"SELECT\n    ROUND(\n        COUNT(DISTINCT CASE\n            WHEN u.SUPPLIERTYPENAME = '前五大上游'\n             AND u.SUPPLIER IS NOT NULL\n             AND EXISTS (\n                 SELECT 1\n                 FROM APP_SETTLE_COUNTERPARTY_INFO s\n                 WHERE s.REPORTNO = u.REPORTNO\n                   AND s.CUSTOMERID = u.CUSTOMERID\n                   AND s.CUSTOMERNAME = u.CUSTOMERNAME\n                   AND s.DIRECTION = '借方'\n                   AND s.RANKNO IN (\n                       'TOP1', 'TOP2', 'TOP3', 'TOP4', 'TOP5',\n                       'TOP6', 'TOP7', 'TOP8', 'TOP9', 'TOP10'\n                   )\n                   AND s.COUNTERPARTYNAME = u.SUPPLIER\n  AND s.reportno = :reportNo\n  AND s.customername = :entName\n             )\n            THEN u.SUPPLIER\n        END) * 100.0\n        / NULLIF(\n            COUNT(DISTINCT CASE\n                WHEN u.SUPPLIERTYPENAME = '前五大上游'\n                THEN u.SUPPLIER\n            END),\n            0\n        ),\n        2\n    ) AS 前五大上游与借方前十大匹配率,\n\n    ROUND(\n        COUNT(DISTINCT CASE\n            WHEN u.SUPPLIERTYPENAME = '前五大下游'\n             AND u.SUPPLIER IS NOT NULL\n             AND EXISTS (\n                 SELECT 1\n                 FROM APP_SETTLE_COUNTERPARTY_INFO s\n                 WHERE s.REPORTNO = u.REPORTNO\n                   AND s.CUSTOMERID = u.CUSTOMERID\n                   AND s.CUSTOMERNAME = u.CUSTOMERNAME\n                   AND s.DIRECTION = '贷方'\n                   AND s.RANKNO IN (\n                       'TOP1', 'TOP2', 'TOP3', 'TOP4', 'TOP5',\n                       'TOP6', 'TOP7', 'TOP8', 'TOP9', 'TOP10'\n                   )\n                   AND s.COUNTERPARTYNAME = u.SUPPLIER\n  AND s.reportno = :reportNo\n  AND s.customername = :entName\n             )\n            THEN u.SUPPLIER\n        END) * 100.0\n        / NULLIF(\n            COUNT(DISTINCT CASE\n                WHEN u.SUPPLIERTYPENAME = '前五大下游'\n                THEN u.SUPPLIER\n            END),\n            0\n        ),\n        2\n    ) AS 前五大下游与贷方前十大匹配率\nFROM APP_TOP_FIVE_UPDOWN_INFO u\nWHERE u.REPORTNO = :reportNo\nAND u.CUSTOMERNAME = :entName\nAND u.SUPPLIERTYPENAME IN ('前五大上游', '前五大下游')","paramData":[{"id":"38a09880-39f7-bfed-a329-5f81d64fd4f6","name":"reportNo","desc":"","type":"1","isSync":"Y","defaultValue":"'RPT-202603-001'","relateIndex":null},{"id":"4333b0d6-3a4d-bea5-20e3-5923ba7e1c1a","name":"entName","desc":"","type":"1","isSync":"Y","defaultValue":"'苏州XX精密机械制造有限公司'","relateIndex":null}],"moduleCode":"","knowledgeCode":"","knowledgeName":"","knowledgeGroupInfo":[],"withModelSummary":false,"knowledgeParamList":[{"key":"1","paramName":"entName","paramValue":"科大讯飞股份有限公司"}],"entName":"科大讯飞股份有限公司"}
