UPDATE index_params SET script = $mig$
{"dataSource":"bosz-dev-local-0001","sql":"SELECT\n    i.ID AS ID,\n    i.REPORTNO AS 报告编号,\n    i.CUSTOMERID AS 客户编号,\n    i.CUSTOMERNAME AS 客户名称,\n    i.SUBJECTTYPE AS 主体类型,\n    i.SUBJECTNAME AS 主体名称,\n    i.eventTypeOrder AS 舆情事件排序,\n    CASE\n        WHEN i.SUBJECTTYPE = '借款人' THEN c.ISLISTEDCOMPANY\n        WHEN i.SUBJECTTYPE = '股东' THEN s.IS_QUOTED\n    END AS 是否上市,\n    CASE\n        WHEN i.SUBJECTTYPE = '股东' THEN s.STOCK_PERCENT\n    END AS 持股比例,\n    i.EVENTTIME AS 舆情发生时间,\n    i.EVENTTYPE AS 舆情类型,\n    i.EVENTDESC AS 舆情事件描述,\n    i.INPUTTIME AS 入库时间\nFROM APP_REPUTATION_EVENT_INFO i\nLEFT JOIN APP_CUSTOMER_INFO c\n    ON c.REPORTNO = i.REPORTNO\n    AND c.CUSTOMERID = i.CUSTOMERID\n    AND c.CUSTOMERNAME = i.CUSTOMERNAME\n    AND i.SUBJECTTYPE = '借款人'\n    AND i.SUBJECTNAME = c.CUSTOMERNAME\n    AND c.reportno = :reportNo\n    AND c.customername = :entName\nLEFT JOIN APP_SHAREHOLDER_INFO s\n    ON s.REPORTNO = i.REPORTNO\n    AND s.CUSTOMERID = i.CUSTOMERID\n    AND s.CUSTOMERNAME = i.CUSTOMERNAME\n    AND i.SUBJECTTYPE = '股东'\n    AND i.SUBJECTNAME = s.NAME\n    AND s.reportno = :reportNo\n    AND s.customername = :entName\nWHERE i.REPORTNO = :reportNo\nAND i.CUSTOMERNAME = :entName\nAND i.EVENTTYPE IN (\n    '证券市场违规问题',\n    '企业股票戴帽',\n    '企业有退市风险',\n    '企业评级被下调',\n    '企业高管无法履职',\n    '财务造假'\n)\nAND (\n    (\n        i.SUBJECTTYPE = '借款人'\n        AND c.ISLISTEDCOMPANY = '是'\n    )\n    OR\n    (\n        i.SUBJECTTYPE = '股东'\n        AND s.IS_QUOTED = '是'\n    )\n)","paramData":[{"id":"aaa66566-dbcc-e75c-fb3a-daecfeaa2200","name":"reportNo","desc":"","type":"1","isSync":"Y","defaultValue":"'RPT-202603-001'","relateIndex":null},{"id":"fb2fd6b5-b1f5-ffbc-e170-ed7d91551643","name":"entName","desc":"","type":"1","isSync":"Y","defaultValue":"'苏州XX精密机械制造有限公司'","relateIndex":null}],"moduleCode":"","knowledgeCode":"","knowledgeName":"","knowledgeGroupInfo":[],"withModelSummary":false,"knowledgeParamList":[{"key":"1","paramName":"entName","paramValue":"科大讯飞股份有限公司"}],"entName":"科大讯飞股份有限公司"}
$mig$ WHERE paramno = '2098316981716398082';

UPDATE index_params SET script = $mig$
{"dataSource":"bosz-dev-local-0001","sql":"SELECT\n    CASE\n        WHEN EXISTS (\n            SELECT 1\n            FROM APP_REPUTATION_EVENT_INFO r\n            WHERE r.REPORTNO = c.REPORTNO\n              AND r.CUSTOMERID = c.CUSTOMERID\n              AND r.CUSTOMERNAME = c.CUSTOMERNAME\n              AND r.SUBJECTTYPE = '借款人'\n              AND r.SUBJECTNAME = c.CUSTOMERNAME\n              AND r.EVENTTYPE IN (\n                  '证券市场违规问题',\n                  '企业股票戴帽',\n                  '企业有退市风险',\n                  '企业评级被下调',\n                  '企业高管无法履职',\n                  '财务造假'\n              )\n  AND r.reportno = :reportNo\n  AND r.customername = :entName\n        )\n        THEN '是'\n        ELSE '否'\n    END AS 借款人是否有重大舆情,\n\n    CASE\n        WHEN EXISTS (\n            SELECT 1\n            FROM APP_REPUTATION_EVENT_INFO r\n            INNER JOIN APP_SHAREHOLDER_INFO s\n                ON s.REPORTNO = r.REPORTNO\n                AND s.CUSTOMERID = r.CUSTOMERID\n                AND s.CUSTOMERNAME = r.CUSTOMERNAME\n                AND s.NAME = r.SUBJECTNAME\n    AND s.reportno = :reportNo\n    AND s.customername = :entName\n            WHERE r.REPORTNO = c.REPORTNO\n              AND r.CUSTOMERID = c.CUSTOMERID\n              AND r.CUSTOMERNAME = c.CUSTOMERNAME\n              AND r.SUBJECTTYPE = '股东'\n              AND s.IS_QUOTED = '是'\n              AND r.EVENTTYPE IN (\n                  '证券市场违规问题',\n                  '企业股票戴帽',\n                  '企业有退市风险',\n                  '企业评级被下调',\n                  '企业高管无法履职',\n                  '财务造假'\n              )\n  AND r.reportno = :reportNo\n  AND r.customername = :entName\n        )\n        THEN '是'\n        ELSE '否'\n    END AS 上市股东是否有重大舆情,\n\n    COALESCE((\n        SELECT SUM(s.STOCK_PERCENT)\n        FROM APP_SHAREHOLDER_INFO s\n        WHERE s.REPORTNO = c.REPORTNO\n          AND s.CUSTOMERID = c.CUSTOMERID\n          AND s.CUSTOMERNAME = c.CUSTOMERNAME\n          AND s.IS_QUOTED = '是'\n  AND s.reportno = :reportNo\n  AND s.customername = :entName\n    ), 0) AS 上市股东持股比例合计\n\nFROM APP_CUSTOMER_INFO c\nWHERE c.REPORTNO = :reportNo\nAND c.CUSTOMERNAME = :entName","paramData":[{"id":"aaa66566-dbcc-e75c-fb3a-daecfeaa2200","name":"reportNo","desc":"","type":"1","isSync":"Y","defaultValue":"'RPT-202603-001'","relateIndex":null},{"id":"fb2fd6b5-b1f5-ffbc-e170-ed7d91551643","name":"entName","desc":"","type":"1","isSync":"Y","defaultValue":"'苏州XX精密机械制造有限公司'","relateIndex":null}],"moduleCode":"","knowledgeCode":"","knowledgeName":"","knowledgeGroupInfo":[],"withModelSummary":false,"knowledgeParamList":[{"key":"1","paramName":"entName","paramValue":"科大讯飞股份有限公司"}],"entName":"科大讯飞股份有限公司"}
