UPDATE index_params SET script = $mig$
{"dataSource":"bosz-dev-local-0001","sql":"SELECT\n    t.ID AS ID,\n    t.REPORTNO AS 报告编号,\n    t.CUSTOMERID AS 客户编号,\n    t.CUSTOMERNAME AS 客户名称,\n    t.TAXPERIOD AS 纳税期,\n    t.MONTHLYTAXSALES AS 每月纳税销售额,\n    t.TOTALSALESTAX AS 当年纳税销售额累计,\n    t.YOYCHANGE AS 当年销售额较上年同期变动额,\n    t.YOYRATE AS 当年销售额较上年同期同比,\n    '最新一期' AS 时间类型,\n    f.REVENUE AS 营业收入,\n    ROUND(\n        ABS(t.TOTALSALESTAX - f.REVENUE),\n        2\n    ) AS 纳税申报销售总额与当期报表相差金额,\n    ROUND(\n        ABS(t.TOTALSALESTAX - f.REVENUE)\n        / NULLIF(f.REVENUE, 0) * 100,\n        2\n    ) AS 纳税申报销售总额与当期报表相差幅度\nFROM APP_GS_TAX_SALES_INFO t\nCROSS JOIN (\n    SELECT\n        MAX(ACCOUNTMONTH) AS MAX_MONTH\n    FROM APP_FINANCE_INDICATOR_INFO\n    WHERE REPORTNO = :reportNo\n    AND CUSTOMERNAME = :entName\n) m\nLEFT JOIN APP_FINANCE_INDICATOR_INFO f\n    ON f.REPORTNO = t.REPORTNO\n    AND f.CUSTOMERID = t.CUSTOMERID\n    AND f.CUSTOMERNAME = t.CUSTOMERNAME\n    AND f.REPORTSCOPE = '本部'\n  AND f.subjectType='借款人'\n    AND f.ACCOUNTMONTH = t.TAXPERIOD\n    AND f.reportno = :reportNo\n    AND f.customername = :entName\nWHERE t.REPORTNO = :reportNo\nAND t.CUSTOMERNAME = :entName\nAND t.TAXPERIOD = m.MAX_MONTH","paramData":[{"id":"54b10e26-eac0-d8dd-0c52-1154a40f3c5a","name":"reportNo","desc":"","type":"1","isSync":"Y","defaultValue":"'RPT-202603-001'","relateIndex":null},{"id":"6c7e9878-e4ba-ae73-4754-f3f5165bb750","name":"entName","desc":"","type":"1","isSync":"Y","defaultValue":"'苏州XX精密机械制造有限公司'","relateIndex":null}],"moduleCode":"","knowledgeCode":"","knowledgeName":"","knowledgeGroupInfo":[],"withModelSummary":false,"knowledgeParamList":[{"key":"1","paramName":"entName","paramValue":"科大讯飞股份有限公司"}],"entName":"科大讯飞股份有限公司"}
