UPDATE index_params SET script = $mig$
{"dataSource":"bosz-dev-local-0001","sql":"SELECT\n    f.ACCOUNTMONTH AS 会计月,\n    g.THISYEAR AS 国税最新一期日期,\n\n    f.REVENUE AS 财报营业收入,\n    g.GFREVENUE AS 国税营业收入,\n    ROUND(\n        ABS(f.REVENUE - g.GFREVENUE)\n        / NULLIF(ABS(f.REVENUE), 0) * 100,\n        2\n    ) AS 营业收入偏差幅度,\n\n    f.ACCOUNTSRECEIVABLE AS 财报应收账款,\n    g.GFRECEIVABLE AS 国税应收账款,\n    ROUND(\n        ABS(f.ACCOUNTSRECEIVABLE - g.GFRECEIVABLE)\n        / NULLIF(ABS(f.ACCOUNTSRECEIVABLE), 0) * 100,\n        2\n    ) AS 应收账款偏差幅度,\n\n    f.ACCOUNTSPAYABLE AS 财报应付账款,\n    g.GFPAYABLE AS 国税应付账款,\n    ROUND(\n        ABS(f.ACCOUNTSPAYABLE - g.GFPAYABLE)\n        / NULLIF(ABS(f.ACCOUNTSPAYABLE), 0) * 100,\n        2\n    ) AS 应付账款偏差幅度,\n\n    f.INVENTORY AS 财报存货,\n    g.GFINVENTORY AS 国税存货,\n    ROUND(\n        ABS(f.INVENTORY - g.GFINVENTORY)\n        / NULLIF(ABS(f.INVENTORY), 0) * 100,\n        2\n    ) AS 存货偏差幅度\n\nFROM APP_FINANCE_INDICATOR_INFO f\nLEFT JOIN APP_GS_FINANCE_DATA_INFO g\n    ON f.REPORTNO = g.REPORTNO\n    AND f.CUSTOMERID = g.CUSTOMERID\n    AND f.CUSTOMERNAME = g.CUSTOMERNAME\n    AND g.REPORTSCOPE = '本部'\n    AND g.reportno = :reportNo\n    AND g.customername = :entName\nWHERE f.REPORTNO = :reportNo\n  AND f.CUSTOMERNAME = :entName\n  AND f.REPORTSCOPE = '本部'\n  AND f.subjectType='借款人'\n  AND f.ACCOUNTMONTH = (\n      SELECT MAX(f2.ACCOUNTMONTH)\n      FROM APP_FINANCE_INDICATOR_INFO f2\n      WHERE f2.REPORTNO = :reportNo\n        AND f2.CUSTOMERNAME = :entName\n          AND f2.subjectType='借款人'\n  )\nLIMIT 1","paramData":[{"id":"54b10e26-eac0-d8dd-0c52-1154a40f3c5a","name":"reportNo","desc":"","type":"1","isSync":"Y","defaultValue":"'RPT-202603-001'","relateIndex":null},{"id":"6c7e9878-e4ba-ae73-4754-f3f5165bb750","name":"entName","desc":"","type":"1","isSync":"Y","defaultValue":"'苏州XX精密机械制造有限公司'","relateIndex":null}],"moduleCode":"","knowledgeCode":"","knowledgeName":"","knowledgeGroupInfo":[],"withModelSummary":false,"knowledgeParamList":[{"key":"1","paramName":"entName","paramValue":"科大讯飞股份有限公司"}],"entName":"科大讯飞股份有限公司"}
