{"dataSource":"bosz-dev-local-0001","sql":"SELECT\n    c.ID AS ID,\n    c.REPORTNO AS 报告编号,\n    c.CUSTOMERID AS 客户编号,\n    c.CUSTOMERNAME AS 客户名称,\n    c.QUERYTIME AS 征信查询时间,\n\n    f.ACCOUNTMONTH AS 会计月,\n\n    f.SHORTLOAN AS 财报短期借款,\n    c.SHORTTERMLOANBAL AS 征信短期借款未结清余额,\n    ROUND(\n        c.SHORTTERMLOANBAL - f.SHORTLOAN,\n        2\n    ) AS 征信短期借款相差,\n\n    f.LONGLOAN AS 财报长期借款,\n    f.LONGLOANDUEWITHIN1Y AS 一年内到期长期借款,\n    c.MIDLONGTERMLOANBAL AS 征信中长期借款未结清余额,\n    ROUND(\n        c.MIDLONGTERMLOANBAL\n        - COALESCE(f.LONGLOAN, 0)\n        - COALESCE(f.LONGLOANDUEWITHIN1Y, 0),\n        2\n    ) AS 征信中长期借款相差,\n\n    ROUND(\n        ABS(\n            COALESCE(c.SHORTTERMLOANBAL, 0)\n            + COALESCE(c.MIDLONGTERMLOANBAL, 0)\n            - COALESCE(f.SHORTLOAN, 0)\n            - COALESCE(f.LONGLOAN, 0)\n            - COALESCE(f.LONGLOANDUEWITHIN1Y, 0)\n        )\n        / NULLIF(\n            ABS(\n                COALESCE(f.SHORTLOAN, 0)\n                + COALESCE(f.LONGLOAN, 0)\n                + COALESCE(f.LONGLOANDUEWITHIN1Y, 0)\n            ),\n            0\n        ) * 100,\n        2\n    ) AS 征信债务偏离度,\n\n    c.GUARANTEEBALANCEEXBANK AS 对外担保余额（剔除我行）,\n    f.TOTALEQUITY AS 所有者权益,\n\n    ROUND(\n        c.GUARANTEEBALANCEEXBANK\n        / NULLIF(f.TOTALEQUITY, 0) * 100,\n        2\n    ) AS 对外担保净资产比\n\nFROM APP_CREDIT_REPORT_INFO c\n\nINNER JOIN APP_FINANCE_INDICATOR_INFO f\n    ON f.REPORTNO = c.REPORTNO\n    AND f.CUSTOMERID = c.CUSTOMERID\n    AND f.CUSTOMERNAME = c.CUSTOMERNAME\n    AND f.GUARANTORID = c.GUARANTORID\n    AND f.GUARANTORNAME = c.GUARANTORNAME\n    AND f.REPORTSCOPE = '本部'\n    AND f.reportno = :reportNo\n    AND f.customername = :entName\n\nWHERE c.REPORTNO = :reportNo\n  AND c.CUSTOMERNAME = :entName\n  AND c.GUARANTORNAME = :guarantorName\n\n  AND f.ACCOUNTMONTH = (\n      SELECT MAX(f2.ACCOUNTMONTH)\n      FROM APP_FINANCE_INDICATOR_INFO f2\n      WHERE f2.REPORTNO = c.REPORTNO\n        AND f2.CUSTOMERID = c.CUSTOMERID\n        AND f2.CUSTOMERNAME = c.CUSTOMERNAME\n        AND f2.GUARANTORID = c.GUARANTORID\n        AND f2.GUARANTORNAME = c.GUARANTORNAME\n        AND f2.REPORTSCOPE = '本部'\n  AND f2.reportno = :reportNo\n  AND f2.customername = :entName\n  )\n\n  AND c.QUERYTIME >= TO_DATE(f.ACCOUNTMONTH || '01', 'YYYYMMDD')\n  AND c.QUERYTIME < ADD_MONTHS(\n      TO_DATE(f.ACCOUNTMONTH || '01', 'YYYYMMDD'),\n      4\n  )\n\nLIMIT 1","paramData":[{"id":"2a9152b1-8542-a0db-0c17-d11b59c4d460","name":"reportNo","desc":"","type":"1","isSync":"Y","defaultValue":"'RPT-202603-001'","relateIndex":null},{"id":"bd138d27-b35d-1604-20e3-ac40f629e622","name":"entName","desc":"","type":"1","isSync":"Y","defaultValue":"'苏州XX精密机械制造有限公司'","relateIndex":null},{"id":"63fa1a6a-7dec-c102-848f-8cd76318565c","name":"guarantorName","desc":"","type":"1","isSync":"Y","defaultValue":"'苏州XX精密机械制造有限公司'","relateIndex":null}],"moduleCode":"","knowledgeCode":"","knowledgeName":"","knowledgeGroupInfo":[],"withModelSummary":false,"knowledgeParamList":[{"key":"1","paramName":"entName","paramValue":"科大讯飞股份有限公司"}],"entName":"科大讯飞股份有限公司"}
$mig$ WHERE paramno = '2099504086844977154';

UPDATE index_params SET script = $mig$
{"dataSource":"bosz-dev-local-0001","sql":"SELECT\n    c.ACTUALCONTROLLER AS 信贷实控人,\n    i.ICBENEFICIARYNAME AS 工商受益人,\n    CASE\n        WHEN c.ACTUALCONTROLLER = i.ICBENEFICIARYNAME THEN '是'\n        ELSE '否'\n    END AS 是否一致\nFROM APP_CUSTOMER_INFO c\nLEFT JOIN APP_IC_INFO i\n    ON c.REPORTNO = i.REPORTNO\n    AND c.CUSTOMERID = i.CUSTOMERID\n    AND c.CUSTOMERNAME = i.CUSTOMERNAME\n    AND i.reportno = :reportNo\n    AND i.customername = :entName\nWHERE c.REPORTNO = :reportNo\n  AND c.CUSTOMERNAME = :entName","paramData":[{"id":"aaa66566-dbcc-e75c-fb3a-daecfeaa2200","name":"reportNo","desc":"","type":"1","isSync":"Y","defaultValue":"'RPT-202603-001'","relateIndex":null},{"id":"fb2fd6b5-b1f5-ffbc-e170-ed7d91551643","name":"entName","desc":"","type":"1","isSync":"Y","defaultValue":"'苏州XX精密机械制造有限公司'","relateIndex":null}],"moduleCode":"","knowledgeCode":"","knowledgeName":"","knowledgeGroupInfo":[],"withModelSummary":false,"knowledgeParamList":[{"key":"1","paramName":"entName","paramValue":"科大讯飞股份有限公司"}],"entName":"科大讯飞股份有限公司"}
